begin;
select plan(10);
insert into auth.users (id) values ('a8111111-1111-4111-8111-111111111111'), ('a8222222-2222-4222-8222-222222222222');
select ok(has_table_privilege('authenticated', 'library.appearance_preferences', 'select'), 'la préférence est lisible par son propriétaire');
select ok(has_table_privilege('authenticated', 'library.appearance_preferences', 'insert'), 'la préférence est enregistrable par la transaction authentifiée');
select ok(not has_table_privilege('anon', 'library.appearance_preferences', 'select'), 'anon ne lit pas une apparence privée');
set local role authenticated;
select set_config('request.jwt.claim.sub', 'a8111111-1111-4111-8111-111111111111', true);
select lives_ok($$insert into library.appearance_preferences (user_id, structure_id, finish_id, request_sha256) values ('a8111111-1111-4111-8111-111111111111', 'frame', 'oak', repeat('a', 64))$$, 'le propriétaire persiste sa structure et sa finition');
select results_eq($$select count(*)::int from library.appearance_preferences$$, $$values (1)$$, 'le propriétaire relit sa préférence');
select set_config('request.jwt.claim.sub', 'a8222222-2222-4222-8222-222222222222', true);
select is_empty($$select 1 from library.appearance_preferences$$, 'un autre utilisateur ne lit pas la préférence');
select throws_ok($$insert into library.appearance_preferences (user_id, structure_id, finish_id, request_sha256) values ('a8111111-1111-4111-8111-111111111111', 'frame', 'oak', repeat('b', 64))$$, '42501', null, 'un autre utilisateur ne forge pas la préférence');
reset role;
select throws_ok($$insert into library.appearance_preferences (user_id, structure_id, finish_id, request_sha256) values ('a8111111-1111-4111-8111-111111111111', 'paid', 'oak', repeat('b', 64))$$, '23514', null, 'une structure non autorisée est refusée');
select ok(not exists (select 1 from information_schema.columns where table_schema = 'library' and table_name = 'appearance_preferences' and column_name = 'placement_id'), 'la préférence ne porte aucune mutation de placement');
select ok(exists (select 1 from pg_constraint where conrelid = 'library.appearance_preferences'::regclass and pg_get_constraintdef(oid) like '%structure_id%'), 'les options sont bornées en base');
select * from finish();
rollback;
